  "result": "{\"email_id\": \"4\", \"folder\": \"INBOX\", \"subject\": \"Draft programme, 2026 workshop\", \"from_addr\": \"ops@galapagos-data.example\", \"to_addr\": \"linqiao@example.com, participants@galapagos-data.example\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-07-03T15:10:00-06:00\", \"message_id\": \"<gdfo-2026-programme-draft@galapagos-data.example>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"All,\\n\\nAttached is the draft programme. Day one is instrumentation and station metadata, day two is the shore transect and sample logging, day three is the tortoise-reserve dataset, day four is joint analysis and the closing session.\\n\\nThe shore transect on day two is the only outdoor session and depends on marine conditions. Bring closed shoes, a hat and a refillable bottle. Single-use plastics are not permitted anywhere in the park.\\n\\nMarisol\", \"body_html\": null, \"attachments\": [{\"attachment_id\": \"att_00000004\", \"filename\": \"expense-guide.pdf\", \"content_type\": \"text/plain\", \"size\": 1492}]}"
