  "result": "{\"email_id\": \"26\", \"folder\": \"INBOX\", \"subject\": \"Re: rooms in August\", \"from_addr\": \"reservas@jardintranquilo.example.com\", \"to_addr\": \"linqiao@example.com\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-07-11T17:45:00-06:00\", \"message_id\": \"<santa-cruz-lodging-enquiry-reply@example.com>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"Good afternoon,\\n\\nAugust is our busiest month. We hold a small number of flexible-rate rooms and release the rest as prepaid. Prepaid rooms are cheaper and cannot be refunded or moved.\\n\\nWe are about fifteen minutes on foot from the Marine Data Lab. Rooms at the front are lively in the evening; the garden side is quiet.\\n\\nReservas, Jardin Tranquilo\", \"body_html\": null, \"attachments\": []}"
