structuredContent:
{
  "result": "{\"email_id\": \"28\", \"folder\": \"INBOX\", \"subject\": \"Itabaca Channel crossing: general information\", \"from_addr\": \"info@canaldeitabaca.example.com\", \"to_addr\": \"linqiao@example.com\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-07-13T09:00:00-06:00\", \"message_id\": \"<ferry-operator-general-info@example.com>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"Thank you for your enquiry. The channel crossing between Baltra and Santa Cruz is a short barge, a few minutes, and runs through the day in normal conditions. It is not a substitute for the road transfer on either side; allow for the bus, the crossing and the drive.\\n\\nWe do not take reservations. Crossings pause in bad weather.\", \"body_html\": null, \"attachments\": []}"
}

structuredContent:
{
  "result": "{\"email_id\": \"29\", \"folder\": \"INBOX\", \"subject\": \"Visiting the Galapagos National Park\", \"from_addr\": \"visitantes@parquegalapagos.example.ec\", \"to_addr\": \"linqiao@example.com\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-06-28T12:00:00-06:00\", \"message_id\": \"<parkservice-general-visitor-info@example.ec>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"General visitor information.\\n\\nEvery visitor to the archipelago must hold a transit control card, obtained before boarding the domestic flight, and must pay the national park entrance fee. Both are per person and both are collected in cash at the airport in practice, although card terminals exist and sometimes work.\\n\\nRates are published by the ministry and are revised from time to time; check the current figures shortly before you travel rather than relying on an older itinerary.\\n\\nNo single-use plastics may be brought into the park.\", \"body_html\": null, \"attachments\": []}"
}

structuredContent:
{
  "result": "{\"email_id\": \"30\", \"folder\": \"INBOX\", \"subject\": \"Entry requirements for Ecuador\", \"from_addr\": \"consular@example.gov\", \"to_addr\": \"linqiao@example.com\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-06-30T15:00:00-05:00\", \"message_id\": \"<embassy-ec-entry-general@example.gov>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"In reply to your enquiry: holders of ordinary Chinese passports do not require a visa for tourist stays in Ecuador within the published limit. A return or onward ticket and proof of accommodation may be requested on arrival.\\n\\nRequirements for any country you transit are a separate matter and are set by that country, not by Ecuador.\", \"body_html\": null, \"attachments\": []}"
}

