_5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"pg_reimb_crib\"}, \"created_time\": \"2026-04-03T09:10:00+08:00\", \"last_edited_time\": \"2026-04-03T09:10:00+08:00\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"plain_text\": \"A charge that is only held or pre-authorised is not money spent yet. Do not claim it until it has actually settled, and do not assume a released hold ever hit the account.\"}]}}, {\"object\": \"block\", \"id\": \"blk_reference_extra_05\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"pg_reimb_crib\"}, \"created_time\": \"2026-06-01T09:00:00+08:00\", \"last_edited_time\": \"2026-07-20T09:00:00+08:00\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"plain_text\": \"A refundable hold still needs an expiry reminder and a release check.\"}]}}, {\"object\": \"block\", \"id\": \"blk_reference_extra_10\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"pg_reimb_crib\"}, \"created_time\": \"2026-06-01T09:00:00+08:00\", \"last_edited_time\": \"2026-07-20T09:00:00+08:00\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"plain_text\": \"Map the final airport-to-venue chain before relying on an arrival timestamp.\"}]}}, {\"object\": \"block\", \"id\": \"blk_reference_extra_15\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"pg_reimb_crib\"}, \"created_time\": \"2026-06-01T09:00:00+08:00\", \"last_edited_time\": \"2026-07-20T09:00:00+08:00\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"plain_text\": \"Leave the live trip journal minimal until current facts are verified.\"}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
