structuredContent:
{
  "result": "{\"email_id\": \"59\", \"folder\": \"INBOX\", \"subject\": \"Current rates, as requested\", \"from_addr\": \"visitantes@parquegalapagos.example.ec\", \"to_addr\": \"linqiao@example.com\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-08-07T10:20:00-06:00\", \"message_id\": \"<parkservice-current-rates-2026@example.ec>\", \"is_read\": true, \"is_important\": true, \"body_text\": \"In reply to your enquiry about the figures in force this season.\\n\\nThe transit control card is 20 US dollars per person. It is issued at the mainland airport, before the domestic departure, and cannot be bought once you have landed on the islands.\\n\\nThe park entrance fee for foreign adult visitors is 100 US dollars per person, collected on arrival at the island airport.\\n\\nBoth charges apply to every visitor. There is no exemption for an accompanying visitor and no reduction for a conference delegate.\\n\\nCard terminals exist at both points and fail often; the queue does not wait for a retry. Bring the amount in cash, in small notes. Keep both receipts. They are the only proof of payment and neither office reissues one.\\n\\nNo single-use plastics may be brought into the park. Bottles are checked at the island airport.\\n\\nParque Nacional Galapagos\", \"body_html\": null, \"attachments\": []}"
}

structuredContent:
{
  "result": "{\"email_id\": \"60\", \"folder\": \"INBOX\", \"subject\": \"Landing day: what actually happens\", \"from_addr\": \"ops@galapagos-data.example\", \"to_addr\": \"linqiao@example.com, participants@galapagos-data.example\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-08-07T11:00:00-06:00\", \"message_id\": \"<gdfo-2026-arrival-practicalities@galapagos-data.example>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"For those who have not done this route before, the sequence on the day you fly out to the islands.\\n\\nAt the mainland airport, before you check in, there is a separate counter where the transit card is issued. It opens two hours before the domestic departure and the queue is long. Your bag is screened there as well.\\n\\nOn landing, the entrance fee is collected in the arrivals hall before you reach the bags. Cash. Then the shuttle to the barge, the barge, and the road transfer into town.\\n\\nBudget several hours between wheels down and being in Puerto Ayora. People who allow ninety minutes are the ones who arrive after the desk has shut.\\n\\nPartners and guests go through exactly the same two counters and pay exactly the same two charges. The programme does not cover them and I cannot get them through on my list.\\n\\nMarisol\", \"body_html\": null, \"attachments\": []}"
}

structuredContent:
{
  "result": "{\"email_id\": \"57\", \"folder\": \"INBOX\", \"subject\": \"Re: name on ticket\", \"from_addr\": \"service@carrier-ib.example.com\", \"to_addr\": \"linqiao@example.com\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-08-05T11:30:00+02:00\", \"message_id\": \"<carrier-ib-name-policy@carrier-ib.example.com>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"In reply to your question about names.\\n\\nThe name on the ticket must match the travel document exactly, including any middle name that appears on the document's machine-readable zone.\\n\\nBefore ticketing, a name can be corrected at no charge. After ticketing, a name change is not permitted on this fare: the ticket must be voided if still within the void window, or reissued at the fare available on the day.\\n\\nA frequent-flyer or hotel loyalty profile is a separate record and has no bearing on the ticket. A mismatch there is a matter for that programme, not for us.\\n\\nIberia Customer Service\", \"body_html\": null, \"attachments\": []}"
}

structuredContent:
{
  "result": "{\"email_id\": \"61\", \"folder\": \"INBOX\", \"subject\": \"Using your card and cash abroad\", \"from_addr\": \"service@bank.example.com\", \"to_addr\": \"linqiao@example.com\", \"cc_addr\": \"\", \"bcc_addr\": \"\", \"date\": \"2026-08-07T09:40:00+08:00\", \"message_id\": \"<bank-fx-cash-advice@example.com>\", \"is_read\": true, \"is_important\": false, \"body_text\": \"Ahead of your travel dates, a note on cash.\\n\\nCash withdrawals abroad carry a 3 per cent fee with a minimum charge, so several small withdrawals cost noticeably more than one larger one. Withdrawals in a currency other than the local one are converted twice.\\n\\nWhere a merchant offers to charge you in your home currency, decline: their rate is worse than ours.\\n\\nWe cannot guarantee that any individual terminal or machine will accept the card. Carry enough of the local currency for anything that must be paid on the spot, and be aware that some destinations are effectively cash-only despite what the guidebooks say.\\n\\nBank Customer Service\", \"body_html\": null, \"attachments\": []}"
}

